

function parseInit(content) {

    var functionParams = []
    var functionName = "Init"
    // Remove all spaces and newlines to simplify regex matching
    const compressedContent = content.replace(/\s+/g, '');

    // Define regex patterns for different function declaration styles
    const patterns = [
        `${functionName}\\(([^)]+)\\)`, // Standard function declaration
        `${functionName}=function\\(([^)]+)\\)`, // Assignment style
        `${functionName}:function\\(([^)]+)\\)`, // Object method style
    ];

    // Try each pattern
    for (const pattern of patterns) {
        const regex = new RegExp(pattern, 'i');
        const match = compressedContent.match(regex);
        if (match) {
            functionParams = match[1].split(',').map(param => {
                const [, type] = param.trim().split(':');
                return type ? type.trim() : '';
            }).filter(Boolean); // Remove empty strings
        }
    }
    return functionParams
}

function parseNew(content) {
    var functionParams = []
    // Remove all spaces and newlines to simplify regex matching
    const compressedContent = content.replace(/\s+/g, '');

    // Define regex patterns for different function declaration styles
    const patterns = [
        `function[A-Za-z0-9_]*\\.new\\(([^)]+)\\)`, // Standard class constructor
        `[A-Za-z0-9_]*\\.new=function\\(([^)]+)\\)`, // Assignment style
    ];

    // Try each pattern
    for (const pattern of patterns) {
        const regex = new RegExp(pattern, 'i');
        const match = compressedContent.match(regex);
        if (match) {
            functionParams = match[1].split(',').map(param => {
                const [, type] = param.trim().split(':');
                return type ? type.trim() : '';
            }).filter(Boolean); // Remove empty strings
        }
    }
    return functionParams
}


function parseFunction(content) {
    var functionParams = []
    var functionName = "returnfunction"
    // Remove all spaces and newlines to simplify regex matching
    const compressedContent = content.replace(/\s+/g, '');

    // Define regex patterns for different function declaration styles
    const patterns = [
        `${functionName}\\(([^)]+)\\)`, // Standard function declaration
    ];

    // Try each pattern
    for (const pattern of patterns) {
        const regex = new RegExp(pattern, 'i');
        const match = compressedContent.match(regex);
        if (match) {
            functionParams = match[1].split(',').map(param => {
                const [, type] = param.trim().split(':');
                return type ? type.trim() : '';
            }).filter(Boolean); // Remove empty strings
        }
    }
    return functionParams
}

function isReturnFunction(content) {
    var lines = content.split('\n').map(line => line.trim())

    for (var i = 0; i < lines.length; i++) {
        var line = lines[i]
        if (line.startsWith('--')) continue
        if (line == "") continue
        if (line.startsWith('return function')) return true
    }
    return false
}

// init or class new
function extractCtorFunctionAndParams(content) {

    var functionName
    var functionParams = []

    // 如果 content 含有 `.new(`, 则 functionName 为 `new`
    if (content.split('\n').some(line => line.includes('function') && line.includes('.new('))) {
        functionName = "new"
        functionParams = parseNew(content)
    }
    // 如果 content 以 `return function` 开头, 则 functionName 为 `function`，这要求 `return function` 前面的内容只能为注释
    else if (isReturnFunction(content)) {
        functionName = "function"
        functionParams = parseFunction(content)
        if (functionParams.length == 0) {
            return undefined
        }
    } else {
        functionName = "Init"
        functionParams = parseInit(content)
    }

    if (functionName == "Init" && functionParams.length == 0) {
        return undefined
    }

    // todo, func parms for class
    return {
        CtorName: functionName,
        Params: functionParams
    };
}


module.exports = extractCtorFunctionAndParams;
